Ltac vo_sc :=
  cbn [sc_denot]; evs; unfold wz in *;
  repeat (first [ rewrite w_sra20 by lia | rewrite w_magic1 by lia | rewrite w_magic2 by lia | rewrite w_mul by lia
                | rewrite w_add by lia ]);
  first [ rewrite br_geu by lia | rewrite br_ltu by lia ]; bool_lia.

Definition VOSAVED : list reg := [25; 24; 23; 22; 21; 20; 19; 18; 9; 8; 1]%bv.
Definition VOK1 : list reg := [3; 4; 21; 26; 27]%bv.

Definition vo_sr1 : list expr := srs sr_id [(10%bv, EVar 32); (11%bv, EVar 33); (2%bv, EVar 34)].
Definition vo_c20 : expr := EMd M_MUL (ELit 20) (EVar 36).
Definition vo_kn1 (clo chi : Z) : list kentry :=
  [ KWord (SA (ELit 0) AGOT_SHBASE) 8 (ELit ASHBASE_CELL);
    KWord (SA (ELit 0) ASHBASE_CELL) 8 (ELit 0x7fff8000);
    KImg 0x10000 0x91000;
    KWord (SA (EVar 32) 0) 8 (EVar 35);
    KWord (SA (EVar 32) 8) 8 (EAlu ALU_ADD (EVar 35) vo_c20);
    KWord (SA (EVar 32) 16) 8 (EAlu ALU_ADD (EVar 35) vo_c20);
    KWr (SA (EVar 34) (-96)) (ELit 96);
    KRange (EVar 34) (2 ^ 45 + 96) (2 ^ 47);
    KRange (EVar 32) 0x6e6000 (2 ^ 47);
    KRange (EVar 35) 0 (2 ^ 47);
    KRange (EVar 36) clo chi;
    KDisj (SA (EVar 32) 0) (ELit 24) (SA (EVar 34) (-96)) (ELit 96) ].
Definition vo_dT : list bool := [false; true; true; false].
Definition vo_dF : list bool := [false].
Definition vo_kn1T : list kentry := Eval vm_compute in kn_fix 20 [AOPNEW] (SCR vo_dT [] []) 0xfb578 vo_sr1 (vo_kn1 2 (2 ^ 24)) 40.
Definition vo_kn1F : list kentry := Eval vm_compute in kn_fix 20 [AOPNEW] (SCR vo_dF [] []) 0xfb578 vo_sr1 (vo_kn1 0 2) 40.
Definition vo_x1T := sym_exec asegs 300 true [AOPNEW] (SCR vo_dT [] []) (SS 0xfb578 vo_sr1 [] vo_kn1T 40) [].
Definition vo_x1F := sym_exec asegs 300 true [AOPNEW] (SCR vo_dF [] []) (SS 0xfb578 vo_sr1 [] vo_kn1F 40) [].
Definition vo_ss1T : sym_state := Eval vm_compute in fst (fst vo_x1T).
Definition vo_ss1F : sym_state := Eval vm_compute in fst (fst vo_x1F).
Definition vo_scs1T : list sidecond := Eval vm_compute in snd (fst vo_x1T).
Definition vo_scs1F : list sidecond := Eval vm_compute in snd (fst vo_x1F).
