Definition vo_E1 (R : bvmap 5 word) (v src spz b cap : Z) : env := Eseed R [wz v; wz src; wz spz; wz b; wz cap].

Lemma vo_kn1_ok : forall (R : bvmap 5 word) (m : mem) (v src spz b cap lo clo chi : Z),
    ACONST m -> mem_inv asegs m -> fldA m v 8 b -> fldA m (v + 8) 8 (b + 20 * cap) -> fldA m (v + 16) 8 (b + 20 * cap) -> gz m v 24 ->
    stk asegs m lo spz -> lo <= spz - 96 -> 2 ^ 45 + 96 <= spz -> spz <= 2 ^ 47 ->
    0x6e6000 <= v -> v + 24 <= 2 ^ 47 -> (v + 24 <= spz - 96 \/ spz <= v) ->
    0 <= b -> b + 20 * cap < 2 ^ 47 -> 0 <= clo -> clo <= cap < chi -> chi <= 2 ^ 24 ->
    know_ok asegs (vo_E1 R v src spz b cap) m (vo_kn1 clo chi).
