Ltac vo_wsolve :=
  unfold wz, sh; rewrite ?ASHADOW_BASE_val;
  repeat (first [ rewrite w_shadd by lia | rewrite w_add by lia | rewrite w_addm by lia | rewrite w_mul by lia | rewrite srl3_v by lia
                | rewrite w_sra20 by lia | rewrite w_magic1 by lia | rewrite w_magic2 by lia ]);
  rewrite ?vgrow_le1, ?vgrow_ge2 by lia;
  first [ reflexivity | f_equal; lia ].

Ltac vo_fin E R HR HR' Hlf Hms KL :=
  lazymatch type of Hlf with log_flat _ ?lg =>
    lazymatch type of Hms with CatSim.msteps _ (@PropExec.mkst _ _ _ ?m0 _) (@PropExec.mkst _ _ _ ?mm _) =>
      change mm with (mem_denot E m0 lg) in Hms;
      let R' := match type of HR' with regs_ok _ _ ?R' => R' end in
      exists R', (mem_denot E m0 lg);
      repeat match goal with |- _ /\ _ => split end;
      [ exact Hms | .. ];
      try apply wmono_mem_denot;
      try (intros r Hr; eapply (syms_same_sound E _ R _ R' KL HR HR'); [vm_compute; reflexivity | exact Hr]);
      try (lazymatch goal with |- getr _ ?r = _ => rrw HR' r; vo_wsolve end)
    end
  end.

Ltac vo_frame E Hlf :=
  first
  [ lazymatch goal with |- munch _ ?m0 (mem_denot _ _ _) =>
      let MU := fresh "MU" in
      pose proof (munch_mem_denot_sb [(-88, 0)] (EVar 34) E m0 _ Hlf ltac:(vm_cast_no_check (@eq_refl bool true))) as MU;
      eapply v4_munch_eqW; [exact MU | cbn [map fst snd]; evs; rewrite u64_of_Z by lia; repeat f_equal; lia] end
  | lazymatch goal with |- rw_cells _ (mem_denot _ _ ?lg) _ _ =>
      change lg with (v4_c8log (EVar 34) (-88) [EVar 25; EVar 24; EVar 23; EVar 22; EVar 21; EVar 20; EVar 19; EVar 18; EVar 9; EVar 8; EVar 1]);
      eapply rw_cells_mem_eq_list;
      [ apply v4_rw_cells_c8log;
        [ exact Hlf | unfold estart; evs; rewrite u64_of_Z by lia; cbn [a_off a_base]; lia
        | cbn [length Z.of_nat Pos.of_succ_nat Pos.succ]; eapply wr_at_of_stk_win; [eassumption | lia | lia] ]
      | reflexivity ] end ].

Definition vo_B1 : Prop :=
  forall (R F : bvmap 5 word) (fc : bv 32) (m : mem) (v b cap src spz lo : Z),
    getr R 10 = wz v -> getr R 11 = wz src -> getr R 2 = wz spz ->
    ACONST m -> mem_inv asegs m -> fldA m v 8 b -> fldA m (v + 8) 8 (b + 20 * cap) -> fldA m (v + 16) 8 (b + 20 * cap) -> gz m v 24 ->
    stk asegs m lo spz -> lo <= spz - 96 -> 2 ^ 45 + 96 <= spz -> spz <= 2 ^ 47 ->
    0x6e6000 <= v -> v + 24 <= 2 ^ 47 -> (v + 24 <= spz - 96 \/ spz <= v) ->
    0 <= b -> b + 20 * cap < 2 ^ 47 -> 0 <= cap < 2 ^ 24 ->
    exists R' M1,
      CatSim.msteps asegs (MS R F (wz 0xfb578) fc None m (seg_rom asegs)) (MS R' F (wz AOPNEW) fc None M1 (seg_rom asegs))
      /\ munch [(spz - 88, spz)] m M1 /\ wmono asegs m M1
      /\ rw_cells asegs M1 (spz - 88) (map (fun r => C8 (getr R r)) VOSAVED)
      /\ getr R' 1 = wz 0xfb67c /\ getr R' 2 = wz (spz - 96) /\ getr R' 8 = wz (v + 8) /\ getr R' 9 = wz v
      /\ getr R' 10 = wz (20 * vgrow cap) /\ getr R' 18 = wz (v + 16) /\ getr R' 19 = wz src /\ getr R' 20 = wz (20 * vgrow cap)
      /\ getr R' 22 = wz (20 * cap) /\ getr R' 23 = wz (sh v) /\ getr R' 24 = wz (sh (v + 8)) /\ getr R' 25 = wz (sh (v + 16))
      /\ (forall r, In r VOK1 -> getr R' r = getr R r).

