Definition vo_B4 : Prop :=
  forall (R F : bvmap 5 word) (fc : bv 32) (m : mem) (v b cap : Z),
    getr R 8 = wz (v + 8) -> getr R 9 = wz v -> getr R 18 = wz (v + 16)
    -> getr R 23 = wz (sh v) -> getr R 24 = wz (sh (v + 8)) -> getr R 25 = wz (sh (v + 16)) ->
    fldA m v 8 b -> fldA m (v + 8) 8 (b + 20 * cap) -> fldA m (v + 16) 8 (b + 20 * cap) -> gz m v 24 ->
    0x6e6000 <= v -> v + 24 <= 2 ^ 47 -> 0 <= b -> b + 20 * cap < 2 ^ 47 -> 0 <= cap < 2 ^ 24 -> (b = 0 -> cap = 0) -> (b <> 0 -> 16 <= b) ->
