                 /\ getr R' 1 = wz 0xfb6c4 /\ getr R' 10 = wz b /\ getr R' 11 = wz (b + 20 * cap) /\ getr R' 12 = wz (b + 20 * cap)
                 /\ getr R' 13 = wz (b + 20 * cap))
