Definition VOK5 : list reg := [2; 3; 4; 8; 9; 18; 19; 20; 21; 24; 25; 26; 27]%bv.
Definition vo_B5 : Prop :=
  forall (R F : bvmap 5 word) (fc : bv 32) (m : mem) (v b cap b' : Z),
    getr R 8 = wz (v + 8) -> getr R 9 = wz v -> getr R 22 = wz (b' + 20 * cap)
    -> getr R 23 = wz (sh v) -> getr R 24 = wz (sh (v + 8)) ->
    fldA m v 8 b -> fldA m (v + 8) 8 (b + 20 * cap) -> gz m v 24 ->
    0x6e6000 <= v -> v + 24 <= 2 ^ 47 -> 0 <= b -> b + 20 * cap < 2 ^ 47 -> 0 <= cap < 2 ^ 24 ->
    0x6e6000 <= b' -> b' + 20 * cap + 20 <= 2 ^ 47 ->
    exists R',
      CatSim.msteps asegs (MS R F (wz 0xfb6c4) fc None m (seg_rom asegs)) (MS R' F (wz AASAN_MEMCPY) fc None m (seg_rom asegs))
      /\ getr R' 1 = wz 0xfb6f0 /\ getr R' 10 = wz b' /\ getr R' 11 = wz b /\ getr R' 12 = wz (20 * cap)
      /\ getr R' 22 = wz b' /\ getr R' 23 = wz (b' + 20 * cap + 20)
